"""Warehouse fulfilment endpoints."""

from __future__ import annotations

from typing import Any

from orders.controllers.http import Response, not_found
from orders.infrastructure.catalog import InMemoryProductCatalog
from orders.infrastructure.customers import InMemoryCustomerRepository
from orders.infrastructure.repository import InMemoryOrderRepository
from orders.infrastructure.stock import InMemoryStockRepository


class FulfilmentController:
    def __init__(
        self,
        orders: InMemoryOrderRepository,
        customers: InMemoryCustomerRepository,
        catalog: InMemoryProductCatalog,
        stock: InMemoryStockRepository,
    ) -> None:
        self._orders = orders
        self._customers = customers
        self._catalog = catalog
        self._stock = stock

    def handle_packing_slip(self, order_id: str) -> Response:
        order = self._orders.get(order_id)
        if order is None:
            return not_found("order")

        if order.status == "cancelled":
            return Response(409, {"error": "order is cancelled"})

        customer = self._customers.get(order.customer_id)
        lines = []
        for item in order.items:
            product = self._catalog.get(item.sku)
            lines.append({
                "sku": item.sku,
                "name": product.name,
                "quantity": item.quantity,
            })

        return Response(200, {
            "order_id": order.order_id,
            "customer_name": customer.name,
            "lines": lines,
        })

    def handle_low_stock(self, threshold: Any) -> Response:
        if type(threshold) is not int or isinstance(threshold, bool) or threshold < 0:
            return Response(400, {"error": "threshold must be a non-negative integer"})

        products = []
        for product in self._catalog.list_all():
            if product.active:
                on_hand = self._stock.get(product.sku)
                if on_hand < threshold:
                    products.append({
                        "sku": product.sku,
                        "name": product.name,
                        "on_hand": on_hand,
                    })

        products.sort(key=lambda p: (p["on_hand"], p["sku"]))

        return Response(200, {"products": products})

def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_packing_slip_success(shop):
    oid = order(shop, "c1", ("BOOK", 2), ("PEN", 1)).body["order_id"]
    response = shop.fulfilment.handle_packing_slip(oid)
    assert response.status == 200
    assert response.body["order_id"] == oid
    assert response.body["customer_name"] == "Ada"
    assert response.body["lines"] == [
        {"sku": "BOOK", "name": "Book", "quantity": 2},
        {"sku": "PEN", "name": "Pen", "quantity": 1},
    ]


def test_packing_slip_unknown_order(shop):
    response = shop.fulfilment.handle_packing_slip("ord-9999")
    assert response.status == 404
